import http from "./httpClient";

// Optional companyId (2026-05-12): when supplied, the backend returns
// per-company AvailableQty on each row and sorts the list so items
// with available stock surface first. Pass it from sales-side
// dropdowns (Edit Bill, Generate Bill from Challan, Standalone Bill);
// admin pages can call without it for the legacy alpha sort.
// `opts.includeAutoGenerated` pulls in the HS-code placeholder rows the tariff
// import creates (one per code, thousands of them). They are excluded by
// default so pickers and the catalog list show the curated items; the Item
// Types screen opts in, together with a search term, when the operator goes
// looking for a placeholder to rename. The server caps that mode's page size.
export const getItemTypes = (companyId, opts = {}) =>
  http.get("/itemtypes", {
    params: {
      ...(companyId ? { companyId } : {}),
      ...(opts.includeAutoGenerated ? { includeAutoGenerated: true } : {}),
      ...(opts.search ? { search: opts.search } : {}),
      ...(opts.take ? { take: opts.take } : {}),
    },
  });
// One page of the WHOLE catalog — hand-created items, HS-import placeholders
// and spreadsheet-imported items together. The Item Catalog screen uses this
// instead of getItemTypes: it pages server-side, so it has no reason to hide
// any of them, and a catalog that hid part of itself is what made imported
// items look missing. Document pickers keep using getItemTypes, which still
// filters, because they render every row they are given.
export const getItemTypesPaged = (companyId, opts = {}) =>
  http.get("/itemtypes/paged", {
    params: {
      ...(companyId ? { companyId } : {}),
      ...(opts.search ? { search: opts.search } : {}),
      page: opts.page || 1,
      ...(opts.pageSize ? { pageSize: opts.pageSize } : {}),
    },
  });

export const getItemTypeById = (id) => http.get(`/itemtypes/${id}`);
export const createItemType = (payload, companyId) =>
  http.post("/itemtypes", payload, { params: companyId ? { companyId } : {} });
export const updateItemType = (id, payload, companyId) =>
  http.put(`/itemtypes/${id}`, payload, { params: companyId ? { companyId } : {} });
export const deleteItemType = (id) => http.delete(`/itemtypes/${id}`);

// One-shot suggestion endpoint — returns valid UOMs, default UOM,
// suggested sale type + rate, and live FBR rate options for an HS Code.
export const getItemTypeFbrHints = (companyId, hsCode) =>
  http.get("/itemtypes/fbr-hints", { params: { companyId, hsCode } });
